// Vite 开发服务器启动示例
import { createServer } from 'vite'

async function startDevServer() {
  // 创建 Vite 开发服务器
  const server = await createServer({
    root: process.cwd(),
    server: {
      port: 5173,
      open: true
    }
  })

  // 启动服务器
  await server.listen()

  // 打印服务器地址
  server.printUrls()
}

startDevServer()

